    private val _sessionToken = MutableStateFlow<String?>(null)
    val sessionToken: StateFlow<String?> = _sessionToken.asStateFlow()

    /**
     * Called by the Activity's PhoneAuthProvider.OnVerificationStateChangedCallbacks.
     * Sends OTP to the given phone number via Firebase Auth.
     */
    fun sendPhoneOtp(
        phone: String,
        onCodeSent: (verificationId: String) -> Unit,
        onAutoVerified: (credential: PhoneAuthCredential) -> Unit,
        onError: (String) -> Unit,
    ) {
        _authLoading.value = true
        _authError.value = null
        _devOtp.value = null

        val formatted = if (phone.startsWith("+")) phone else "+91$phone"
        val callbacks = object : PhoneAuthProvider.OnVerificationStateChangedCallbacks() {
            override fun onVerificationCompleted(credential: PhoneAuthCredential) {
                onAutoVerified(credential)
            }

            override fun onVerificationFailed(e: com.google.firebase.auth.FirebaseAuthException) {
                _authLoading.value = false
                val msg = when {
