        // Set callbacks in AuthManager so it can route the verificationId
        val options = PhoneAuthOptions(
            phone = formatted,
            timeout = 60L,
            timeUnit = TimeUnit.SECONDS,
            activity = this,
            callbacks = callbacks,
        )

        PhoneAuthProvider.verifyPhoneNumber(options.builder.build())
    }

    private fun resendFirebasePhoneVerification(phone: String) {
        val formatted = if (phone.startsWith("+")) phone else "+91$phone"
        // Reuse the same callbacks pattern
        startFirebasePhoneVerification(formatted)
    }

    private data class PhoneAuthOptions(
        val phone: String,
        val timeout: Long,
        val timeUnit: TimeUnit,
        val activity: ComponentActivity,
        val callbacks: PhoneAuthProvider.OnVerificationStateChangedCallbacks,
    ) {
        val builder: com.google.firebase.auth.PhoneAuthOptions.Builder
            get() = com.google.firebase.auth.PhoneAuthOptions.newBuilder()
                .setPhoneNumber(phone)
                .setTimeout(timeout, timeUnit)
                .setActivity(activity)
                .setCallbacks(callbacks)
    }

    private fun requestExactAlarmIfNeeded() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            val alarmManager = getSystemService(ALARM_SERVICE) as AlarmManager
            if (!alarmManager.canScheduleExactAlarms()) {
                Toast.makeText(
                    this,
                    "VitaHero needs exact alarm permission for reminders. Please enable it in Settings.",
                    Toast.LENGTH_LONG
                ).show()
                val intent = Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM).apply {
                    data = Uri.parse("package:$packageName")
                }
                exactAlarmLauncher.launch(intent)
            }
        }
    }
}
